// ABOUTME: BGPopover - A reusable popover component with an arrow pointing to its trigger.
// ABOUTME: Supports hover mode (default) and persistent mode with a close button via hasCloseBtn.

import React, { useRef, useEffect, useState } from 'react'
import { BGPopoverProps } from './types'

/**
 * BGPopover Component
 *
 * A popover that renders arbitrary content next to a trigger element,
 * with an arrow edge pointing back at the trigger.
 *
 * Two modes:
 *  - Hover mode (default): shows on hover, hides on mouse leave.
 *  - Close-button mode (hasCloseBtn=true): controlled via visible/onClose,
 *    renders a close button in the top-right corner.
 *
 * Usage (hover):
 *   <BGPopover trigger={<button data-testid="button-31bd74b3">Hover me</button>} position="bottom">
 *     <p data-testid="p-f6eb32a9">Popover content</p>
 *   </BGPopover>
 *
 * Usage (close button):
 *   <BGPopover
 *     trigger={<button data-testid="button-4c49a30f"  onClick={() => setOpen(true)}>Click me</button>}
 *     hasCloseBtn
 *     visible={isOpen}
 *     onClose={() => setOpen(false)}
 *   >
 *     <p data-testid="p-10308d64">Persistent content</p>
 *   </BGPopover>
 */
const BGPopover: React.FC<BGPopoverProps> = ({
  children,
  trigger,
  position = 'bottom',
  align = 'center',
  bgColorClass = 'bg-primary',
  textColorClass = 'text-backdrop',
  className = '',
  arrowOffset,
  hasCloseBtn = false,
  visible = false,
  onClose,
}) => {
  const [hovered, setHovered] = useState(false)
  const isVisible = hasCloseBtn ? visible : hovered

  const popoverRef = useRef<HTMLDivElement>(null)

  // Click-outside only applies to close-button mode
  useEffect(() => {
    if (!hasCloseBtn || !isVisible || !onClose) return

    const handleClickOutside = (e: MouseEvent) => {
      if (popoverRef.current && !popoverRef.current.contains(e.target as Node)) {
        onClose()
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [hasCloseBtn, isVisible, onClose])

  const isVertical = position === 'top' || position === 'bottom'

  // Panel alignment classes based on position + align
  const alignClasses: Record<string, Record<string, string>> = {
    top: {
      start: 'bottom-full left-0 mb-3',
      center: 'bottom-full left-1/2 -translate-x-1/2 mb-3',
      end: 'bottom-full right-0 mb-3',
    },
    bottom: {
      start: 'top-full left-0 mt-3',
      center: 'top-full left-1/2 -translate-x-1/2 mt-3',
      end: 'top-full right-0 mt-3',
    },
    left: {
      start: 'right-full top-0 mr-3',
      center: 'right-full top-1/2 -translate-y-1/2 mr-3',
      end: 'right-full bottom-0 mr-3',
    },
    right: {
      start: 'left-full top-0 ml-3',
      center: 'left-full top-1/2 -translate-y-1/2 ml-3',
      end: 'left-full bottom-0 ml-3',
    },
  }

  const panelClasses = alignClasses[position][align]

  // Arrow position on the popover edge
  const arrowPositionMap: Record<string, string> = {
    top: 'top-full',
    bottom: 'bottom-full',
    left: 'left-full',
    right: 'right-full',
  }

  // Default arrow offset: for center align = 50%, for start = near start, for end = near end
  const defaultArrowOffset: Record<string, string> = {
    start: '20%',
    center: '50%',
    end: '80%',
  }
  const resolvedArrowOffset = arrowOffset ?? defaultArrowOffset[align]
  const arrowOffsetProp = isVertical ? 'left' : 'top'

  // Build the arrow's inline border style so we don't rely on dynamic Tailwind classes
  const arrowBorderProp: Record<string, string> = {
    top: 'borderTopColor',
    bottom: 'borderBottomColor',
    left: 'borderLeftColor',
    right: 'borderRightColor',
  }

  const panelRef = useRef<HTMLDivElement>(null)
  const [arrowColor, setArrowColor] = useState<string>('transparent')

  useEffect(() => {
    if (isVisible && panelRef.current) {
      const bg = getComputedStyle(panelRef.current).backgroundColor
      setArrowColor(bg)
    }
  }, [isVisible])

  return (
    <div data-testid="div-4d1122cd" 
      ref={popoverRef}
      className="relative inline-block"
      {...(!hasCloseBtn && {
        onMouseEnter: () => setHovered(true),
        onMouseLeave: () => setHovered(false),
      })}
    >
      {trigger}
      {isVisible && (
        <div data-testid="div-657b187d" 
          ref={panelRef}
          className={`
            absolute z-50
            ${panelClasses}
            ${bgColorClass} ${textColorClass}
            rounded-xl shadow-lg
            p-3
            ${className}
          `}
        >
          {/* Arrow pointing back to the trigger */}
          <div data-testid="div-1c3f5f8e" 
            className={`absolute w-0 h-0 border-8 border-solid border-transparent ${arrowPositionMap[position]}`}
            style={{
              [arrowOffsetProp]: resolvedArrowOffset,
              [arrowBorderProp[position]]: arrowColor,
            }}
          />

          {/* Close button */}
          {hasCloseBtn && onClose && (
            <button data-testid="button-8c0b5671" 
              onClick={onClose}
              className={`absolute top-3 right-3.5 ${textColorClass} opacity-70 hover:opacity-100 text-lg leading-none`}
              aria-label="Close"
            >
              &times;
            </button>
          )}

          {children}
        </div>
      )}
    </div>
  )
}

export default BGPopover
