import { useEffect, useMemo, useState } from "react";
import { PageTitle } from "./components/page-title"
import { usePageStore, useRecommendationsStore } from "./state";
import { GoogleDeviceSession, GoogleScanResults, OAPRecommendation } from "@/app/scripts/oap/types";
import { BGSvgIcon } from "@/app/popup/src/components/core";
import { sendBackgroundMessage } from "@/utils/messaging/messaging";
import { DeleteDeviceSessionRequest, DeleteDeviceSessionResponse } from "@/utils/messaging/types";
import { MSG_OAP_DELETE_DEVICE_SESSION } from "@/app/scripts/app-consts";
import { t } from "$Popup/i18n";

export const GoogleConnectedDevicesPage: React.FC = () => {
    const setPage = usePageStore((state) => state.setPage);
    const scanResults = useRecommendationsStore((state) => state.scanResults);
    const recommendations = useRecommendationsStore((state) => state.allRecommendations);
    const updateDeviceSessions = useRecommendationsStore((state) => state.updateDeviceSessions);
    const updateRecommendations = useRecommendationsStore((state) => state.withUpdatedRecommendation);
    const [connectedDevices, setConnectedDevices] = useState<GoogleDeviceSession[]>([]);

    const devicesRecommendation = useMemo(() => {
        return recommendations.find((r) => r.type === 'google-connected-devices');
    }, [recommendations]);

    const initialDevices = useMemo(() => {
        return (scanResults as GoogleScanResults)?.deviceSessions || {};
    }, [scanResults]);

    useEffect(() => {
        console.log("OAP: GoogleConnectedDevicesPage: initialDevices", initialDevices);
        setConnectedDevices(Object.values(initialDevices) as GoogleDeviceSession[]);
    }, [initialDevices]);

    const onBackClicked = () => {
        setPage('overview');
    }

    const onDeviceDeleted = (device: GoogleDeviceSession, updatedRecommendation: OAPRecommendation) => {
        console.debug("OAP: GoogleConnectedDevicesPage: onDeviceDeleted", device);
        console.debug("OAP: GoogleConnectedDevicesPage: connectedDevices", connectedDevices);

        const updatedConnectedDevices = connectedDevices.filter(d => d.sessionId !== device.sessionId)
        console.debug("OAP: GoogleConnectedDevicesPage: updatedConnectedDevices", updatedConnectedDevices);
        setConnectedDevices(updatedConnectedDevices);

        // update the zustand store
        updateDeviceSessions(updatedConnectedDevices);
        updateRecommendations(updatedRecommendation);
    }

    return (
        <>
            <PageTitle title={t('OAPConnectedDevicesPageTitle')} onBackClicked={onBackClicked} />
            {connectedDevices.map((r, idx) => (
                <>
                    {devicesRecommendation && <GoogleDeviceCard key={idx} device={r} onDeviceDeleted={(device, updatedRecommendation) => { onDeviceDeleted(device, updatedRecommendation) }} recommendation={devicesRecommendation} />}
                </>
            ))}
        </>
    )
}

export const GoogleDeviceCard: React.FC<{ device: GoogleDeviceSession, recommendation: OAPRecommendation, onDeviceDeleted: (device: GoogleDeviceSession, updatedRecommendation: OAPRecommendation) => void }> = ({ device, recommendation, onDeviceDeleted }) => {
    const [deleteDeviceLoading, setDeleteDeviceLoading] = useState(false);
    const [deleteDeviceFailed, setDeleteDeviceFailed] = useState(false);
    const osIcon = useMemo(() => {
        return getOsIcon(osNumToName(device.osNum));
    }, [device.osNum]);

    const deleteDeviceClicked = async () => {
        setDeleteDeviceLoading(true);
        setDeleteDeviceFailed(false);
        try {
            const resp = await sendBackgroundMessage<DeleteDeviceSessionRequest, DeleteDeviceSessionResponse>({ type: MSG_OAP_DELETE_DEVICE_SESSION, payload: { device, recommendation } });
            if (resp.payload?.success === true) {
                onDeviceDeleted(device, resp.payload.updatedRecommendation);
            } else {
                setDeleteDeviceFailed(true);
            }
        } finally {
            setDeleteDeviceLoading(false);
        }
    }

    function getOsIcon(os: os | undefined): string | undefined {
        if (!os) {
            return undefined;
        }


        switch (os) {
            case "windows":
                return "oap-platform-windows";
            case "macos":
                return "oap-platform-mac";
            case "android":
                return "oap-platform-android";
            case "android-tv":
                return "oap-platform-android";
            case "ios":
                return "oap-platform-ios";
            case "chrome":
                return undefined;
            default:
                return undefined;
        }
    }

    return (
        <div data-testid="div-52247921"  className="flex flex-col items-start gap-4 self-stretch py-4 px-6 rounded-2xl bg-backdrop border border-solid border-tragic-table-border">
            <div data-testid="div-ca6b9389"  className="flex flex-row gap-2 items-center self-stretch">
                {/* Text content */}
                <div data-testid="div-637eb1a1"  className="flex flex-col justify-center items-start gap-1 grow shrink-0 basis-0">
                    <div data-testid="div-c6af038f"  className="flex gap-2 items-center">
                        {osIcon && <BGSvgIcon iconName={osIcon} size={24} />}
                        <h3 data-testid="h3-dad3b29f"  className="text-base font-medium leading-6 tracking-[0.15px] text-tragic">Session on {osFriendlyName(osNumToName(device.osNum))} device {device.deviceName ? `- ${device.deviceName}` : ""}</h3>
                    </div>
                    {device.lastSeen && <p data-testid="p-be1db070"  className="text-sm font-normal leading-5 tracking-[0.25px] text-tragic opacity-50">Last seen: {device.lastSeen}</p>}
                    {device.location && <p data-testid="p-3090d241"  className="text-sm font-normal leading-5 tracking-[0.25px] text-tragic opacity-80">{device.location}</p>}
                </div>

                {/* Signuout button */}
                <button data-testid="button-a277f009"
                    onClick={deleteDeviceClicked}
                    disabled={deleteDeviceLoading}
                    className="flex flex-row min-w-[88px] px-4 py-2 justify-center items-center gap-1.5 rounded-[50px] bg-primary disabled:opacity-50 cursor-pointer">
                    {deleteDeviceLoading ? (
                        <span data-testid="span-5b5fe973"  className="text-center text-sm font-medium leading-5 tracking-[0.1px] text-backdrop">{t('OAPLoading')}</span>
                    ) : (
                        <span data-testid="span-c53acfe4"  className="text-center text-sm font-medium leading-5 tracking-[0.1px] text-backdrop">{t('OAPSignOut')}</span>
                    )}
                </button>
            </div>

            {deleteDeviceFailed && <span data-testid="span-44f01435"  className="text text-sm font-normal leading-5 text-danger">{t('OAPFailedToDeleteDeviceSession')}</span>}
        </div>
    )
}

type os = 'windows' | 'macos' | 'ios' | 'android' | 'android-tv' | 'linux' | 'chrome' | 'unknown';

function osNumToName(osNum: number | undefined): os | undefined {
    if (!osNum) {
        return undefined;
    }
    switch (osNum) {
        case 1:
            return "windows";
        case 2:
            return "macos";
        case 3:
            return "android";
        case 4:
            return "android-tv";
        case 5:
            return "ios";
        case 6:
            return "chrome";
        case 7:
            return "android-tv";
        default:
            return "unknown";
    }
}

function osFriendlyName(os: os | undefined): string {
    if (!os) {
        return "unknown";
    }

    switch (os) {
        case "windows":
            return "Windows";
        case "macos":
            return "Mac OS";
        case "android":
            return "Android";
        case "android-tv":
            return "Android TV";
        case "ios":
            return "iOS";
        case "chrome":
            return "Chrome";
        default:
            return "unknown";
    }
}
