import {
  GoogleDeviceSessions,
  GoogleDeviceSession,
  GoogleScanResults,
  OAPRecommendation,
  ScanResults,
  GoogleThirdPartyApp,
  RESULTS_VIEW_PAGE_STORAGE_KEY,
} from "@/app/scripts/oap/types";
import { create } from "zustand";

export type ResultsViewPage =
  | "overview"
  | "google-apps-basic-access"
  | "google-apps-extended-access"
  | "google-connected-devices";

export interface MinimizedState {
  minimized: boolean;
  setMinimized: (minimized: boolean) => void;
}

export interface ResultsViewPageState {
  page: ResultsViewPage;
  initPageState: () => Promise<void>;
  setPage: (page: ResultsViewPage) => Promise<void>;
}

export const usePageStore = create<ResultsViewPageState>((set, get) => ({
  page: "overview",
  initPageState: async () => {
    console.log("OAP: initPageState called");
    const result = await chrome.storage.local.get(RESULTS_VIEW_PAGE_STORAGE_KEY);
    console.log("OAP: initPageState result", result);
    set({
      page: (result[RESULTS_VIEW_PAGE_STORAGE_KEY] as ResultsViewPage) || "overview",
    });
  },
  setPage: async (page: ResultsViewPage) => {
    console.log("OAP: setPage called", page);
    set({ page });
    await chrome.storage.local.set({
      [RESULTS_VIEW_PAGE_STORAGE_KEY]: page,
    });
  },
}));

export const useMinimizedStore = create<MinimizedState>((set) => ({
  minimized: false,
  setMinimized: (minimized: boolean) => set({ minimized }),
}));

export interface OAPRecommendationState {
  allRecommendations: OAPRecommendation[];
  scanResults: ScanResults | null;
  setRecommendations: (recommendations: OAPRecommendation[]) => void;
  setScanResults: (scanResults: ScanResults) => void;
  markRecommendationAsDone: (
    recommendation: OAPRecommendation
  ) => Promise<void>;
  skipRecommendation: (recommendation: OAPRecommendation) => Promise<void>;
  bringBackRecommendation: (recommendation: OAPRecommendation) => void;
  updateDeviceSessions: (deviceSessions: GoogleDeviceSession[]) => void;
  updateConnectedApps: (connectedApps: GoogleThirdPartyApp[]) => void;
  withUpdatedRecommendation: (recommendation: OAPRecommendation) => void;
}

export const useRecommendationsStore = create<OAPRecommendationState>(
  (set, get) => ({
    allRecommendations: [],
    scanResults: null,
    setScanResults: (scanResults: ScanResults) => {
      set({ scanResults });
    },
    setRecommendations: (recommendations: OAPRecommendation[]) => {
      set({ allRecommendations: recommendations });
    },
    markRecommendationAsDone: async (recommendation: OAPRecommendation) => {
      const current = get().allRecommendations;
      const updated = current.map((r) =>
        r.type === recommendation.type ? { ...r, resolved: true } : r
      );
      set({ allRecommendations: updated });
    },
    skipRecommendation: async (recommendation: OAPRecommendation) => {
      const current = get().allRecommendations;
      const updated = current.map((r) =>
        r.type === recommendation.type ? { ...r, skipped: true } : r
      );
      set({ allRecommendations: updated });
    },
    bringBackRecommendation: (recommendation: OAPRecommendation) => {
      const current = get().allRecommendations;
      const updated = current.map((r) =>
        r.type === recommendation.type
          ? { ...r, resolved: false, skipped: false }
          : r
      );
      set({ allRecommendations: updated });
    },
    updateDeviceSessions: (deviceSessions: GoogleDeviceSession[]) => {
      const current = get().scanResults;
      if (current) {
        const googleScanResults = current as GoogleScanResults;
        googleScanResults.deviceSessions = deviceSessions.reduce(
          (acc, device) => {
            acc[device.sessionId] = device;
            return acc;
          },
          {} as GoogleDeviceSessions
        );
        set({ scanResults: googleScanResults });
      }
    },
    updateConnectedApps: (connectedApps: GoogleThirdPartyApp[]) => {
      const current = get().scanResults;
      if (current) {
        const googleScanResults = current as GoogleScanResults;
        googleScanResults.thirdPartyApps = connectedApps;
        set({ scanResults: googleScanResults });
      }
    },
    withUpdatedRecommendation: (recommendation: OAPRecommendation) => {
      const current = get().allRecommendations;
      const updated = current.map((r) =>
        r.type === recommendation.type ? { ...r, ...recommendation } : r
      );
      set({ allRecommendations: updated });
    },
  })
);
