import { useState, useMemo, useEffect } from "react";
import { PageTitle } from "./components/page-title";
import { usePageStore, useRecommendationsStore } from "./state";
import { GoogleScanResults, GoogleThirdPartyApp, isScanError, OAPRecommendation } from "@/app/scripts/oap/types";
import { GoogleAppAccessCard } from "./components/google-app-access-card";
import { t } from "$Popup/i18n";

export const GoogleAppsBasicAccessPage: React.FC = () => {
    const setPage = usePageStore((state) => state.setPage);
    const scanResults = useRecommendationsStore((state) => state.scanResults);
    const [basicAccessApps, setBasicAccessApps] = useState<GoogleThirdPartyApp[]>([]);
    const recommendations = useRecommendationsStore((state) => state.allRecommendations);
    const updateRecommendations = useRecommendationsStore((state) => state.withUpdatedRecommendation);
    const updateConnectedApps = useRecommendationsStore((state) => state.updateConnectedApps);
    const appsRecommendation = useMemo(() => {
        return recommendations.find((r) => r.type === 'google-apps-basic-access');
    }, [recommendations]);

    // Initialize apps from scanResults
    const initialApps = useMemo(() => {
        const googleScanResults = scanResults as GoogleScanResults;
        if (isScanError(googleScanResults.thirdPartyApps) || !googleScanResults.thirdPartyApps) {
            return [];
        }
        return googleScanResults.thirdPartyApps.filter(app => app.permissions.length === 1 && app.permissions[0].weight === 0);
    }, [scanResults]);

    // Set the initial apps when scanResults change
    useEffect(() => {
        setBasicAccessApps(initialApps);
    }, [initialApps]);

    const onBackClicked = () => {
        setPage('overview');
    }

    const onConnectionDeleted = async (app: GoogleThirdPartyApp, updatedRecommendation: OAPRecommendation) => {
        const updatedBasicAccessApps = basicAccessApps.filter(a => a.name !== app.name);
        setBasicAccessApps(updatedBasicAccessApps);

        const googleScanResults = scanResults as GoogleScanResults;
        if (isScanError(googleScanResults.thirdPartyApps) || !googleScanResults.thirdPartyApps) {
            return;
        }
        const updatedConnectedApps = googleScanResults.thirdPartyApps.filter(a => app.name !== a.name);
        updateConnectedApps(updatedConnectedApps);
        updateRecommendations(updatedRecommendation);
    }

    return (
        <>
            <PageTitle title={t("oapAppsBasicAccessPageTitle")} onBackClicked={onBackClicked} />
            {basicAccessApps.map((r, idx) => (
                <>
                    {appsRecommendation && <GoogleAppAccessCard key={idx} app={r} onConnectionDeleted={(app, updatedRecommendation) => { onConnectionDeleted(app, updatedRecommendation) }} recommendation={appsRecommendation} />}
                </>
            ))}
        </>
    )
}

export const GoogleAppsExtendedAccessPage: React.FC = () => {
    const setPage = usePageStore((state) => state.setPage);
    const scanResults = useRecommendationsStore((state) => state.scanResults);
    const [extendedAccessApps, setExtendedAccessApps] = useState<GoogleThirdPartyApp[]>([]);
    const recommendations = useRecommendationsStore((state) => state.allRecommendations);
    const updateRecommendations = useRecommendationsStore((state) => state.withUpdatedRecommendation);
    const updateConnectedApps = useRecommendationsStore((state) => state.updateConnectedApps);
    const appsRecommendation = useMemo(() => {
        return recommendations.find((r) => r.type === 'google-apps-extended-access');
    }, [recommendations]);

    const initialApps = useMemo(() => {
        const googleScanResults = scanResults as GoogleScanResults;
        if (isScanError(googleScanResults.thirdPartyApps) || !googleScanResults.thirdPartyApps) {
            return [];
        }
        return googleScanResults.thirdPartyApps.filter(app => app.permissions.some(p => p.weight > 0));
    }, [scanResults]);

    useEffect(() => {
        setExtendedAccessApps(initialApps);
    }, [initialApps]);

    const onBackClicked = () => {
        setPage('overview');
    }

    const onConnectionDeleted = (app: GoogleThirdPartyApp, updatedRecommendation: OAPRecommendation) => {
        const updatedExtendedAccessApps = extendedAccessApps.filter(a => a.name !== app.name);
        setExtendedAccessApps(updatedExtendedAccessApps);

        const googleScanResults = scanResults as GoogleScanResults;
        if (isScanError(googleScanResults.thirdPartyApps) || !googleScanResults.thirdPartyApps) {
            return;
        }
        const updatedConnectedApps = googleScanResults.thirdPartyApps.filter(a => app.name !== a.name);
        updateConnectedApps(updatedConnectedApps);
        updateRecommendations(updatedRecommendation);
        setExtendedAccessApps(extendedAccessApps.filter(a => a.name !== app.name));
    }

    return (
        <>
            <PageTitle title={t("oapAppsExtendedAccessPageTitle")} onBackClicked={onBackClicked} />
            {extendedAccessApps.map((r, idx) => (
                <>
                    {appsRecommendation && <GoogleAppAccessCard key={idx} app={r} onConnectionDeleted={(app, updatedRecommendation) => { onConnectionDeleted(app, updatedRecommendation) }} recommendation={appsRecommendation} />}
                </>
            ))}
        </>
    )
}
