
export function closeOAPResultsView() {
    // Restore body overflow to allow scrolling
    const bodyOverflow = document.body.style.overflow;
    if (bodyOverflow === 'hidden') {
        document.body.style.overflow = '';
    }
    
    const shadowHost = document.querySelectorAll("#bg-oap-results-view");
    if (shadowHost) {
        for (let i = 0; i < shadowHost.length; i++) {
            shadowHost[i].remove();
        }
    }
}
