import React, { useEffect, useState } from "react";
import ReactDOM from "react-dom/client";
// Import processed CSS as a string
import cssText from "@/app/popup/src/styles/css-exporter.js";
import { TopBar } from "./components/top-bar";
import { OAPRecommendation, ScanResults } from "@/app/scripts/oap/types";
import { useMinimizedStore, usePageStore, useRecommendationsStore } from "./state";
import { closeOAPResultsView } from "./helpers";
import { OverviewPage } from "./overview-page";
import { GoogleAppsBasicAccessPage, GoogleAppsExtendedAccessPage } from "./google-apps-pages";
import { BGSvgIcon } from "@/app/popup/src/components/core";
import { GoogleConnectedDevicesPage } from "./google-devices-page";
import bundledIcons from "@/app/popup/src/assets/icons/icons-exporter";

// Make bundled icons available globally for BGSvgIcon in this injectable context
if (typeof window !== 'undefined') {
    window.__BG_BUNDLED_ICONS__ = bundledIcons;
}

console.log("OAP: oap-results-view.tsx loaded");

function createOAPResultsView(recommendations: OAPRecommendation[], scanResults: ScanResults) {
    console.log("OAP: createOAPResultsView called", recommendations);
    const shadowHost = document.createElement("div");
    shadowHost.id = "bg-oap-results-view";

    // inject it in the <html> tag
    document.documentElement.appendChild(shadowHost);
    const shadowRoot = shadowHost.attachShadow({ mode: "open" });

    // Inject compiled CSS into shadow DOM
    try {
        const styleSheet = document.createElement("style");
        styleSheet.textContent = cssText;
        shadowRoot.appendChild(styleSheet);
        console.log("OAP: CSS injected successfully", cssText.length, "characters");
    } catch (error) {
        console.error("OAP: Error injecting CSS:", error);
    }

    const reactContainer = document.createElement("div");
    shadowRoot.appendChild(reactContainer);

    const root = ReactDOM.createRoot(reactContainer);
    root.render(
        <OAPApp recommendations={recommendations} scanResults={scanResults} />
    );
}

const OAPApp: React.FC<{ recommendations: OAPRecommendation[], scanResults: ScanResults }> = ({ recommendations, scanResults }) => {
    const setRecommendations = useRecommendationsStore((state) => state.setRecommendations);
    const setScanResults = useRecommendationsStore((state) => state.setScanResults);

    // Initialize the Zustand store with recommendations
    useEffect(() => {
        setRecommendations(recommendations);
    }, [recommendations, setRecommendations]);

    useEffect(() => {
        setScanResults(scanResults);
    }, [scanResults, setScanResults]);

    return (
        <OAPResultsView />
    );
}

const OAPResultsView: React.FC = () => {
    const initPageState = usePageStore((state) => state.initPageState);
    const page = usePageStore((state) => state.page);
    const setPage = usePageStore((state) => state.setPage);
    const { minimized, setMinimized } = useMinimizedStore();
    const scrollContainerRef = React.useRef<HTMLDivElement>(null);
    const [isMouseOver, setIsMouseOver] = useState(false);
    const originalOverflowRef = React.useRef<string>("");

    useEffect(() => {
        initPageState();
    }, [initPageState]);

    /*
    useEffect(() => {
        // Prevent body scroll only when mouse is over the results view
        if (isMouseOver && !minimized) {
            originalOverflowRef.current = document.body.style.overflow;
            document.body.style.overflow = 'hidden';

            return () => {
                document.body.style.overflow = originalOverflowRef.current;
            };
        }
    }, [isMouseOver, minimized]);

    // Cleanup: Restore scroll on unmount
    useEffect(() => {
        return () => {
            if (originalOverflowRef.current !== undefined) {
                document.body.style.overflow = originalOverflowRef.current;
            }
        };
    }, []);
    */

    const closedClicked = () => {
        setPage('overview');
        closeOAPResultsView();
    }
    const minimizeClicked = () => {
        console.log("OAP: minimizeClicked");
        setMinimized(true);
    }

    const handleWheel = (e: React.WheelEvent<HTMLDivElement>) => {
        const scrollContainer = scrollContainerRef.current;
        if (!scrollContainer) return;

        const { scrollTop, scrollHeight, clientHeight } = scrollContainer;
        const isAtTop = scrollTop === 0;
        const isAtBottom = Math.abs(scrollHeight - clientHeight - scrollTop) < 1;

        // Prevent scroll propagation when at boundaries
        if ((isAtTop && e.deltaY < 0) || (isAtBottom && e.deltaY > 0)) {
            e.preventDefault();
        }
    }

    return (
        <>
            {!minimized ? (
                <div data-testid="div-c5cc7e7f"
                    className="results-view-container fixed top-0 bottom-0 right-0 w-[570px] z-[2147483600] bg-tragic-100 transition-all duration-300 font-roboto"
                    onMouseEnter={() => setIsMouseOver(true)}
                    onMouseLeave={() => setIsMouseOver(false)}
                >
                    <div data-testid="div-64de33d7"  className="flex flex-col w-full h-full">
                        <div data-testid="div-f65a144a"  className="sticky top-0 z-10">
                            <TopBar closedClicked={closedClicked} minimizeClicked={minimizeClicked} />
                        </div>
                        <div data-testid="div-cbc7cb50"
                            ref={scrollContainerRef}
                            className="flex flex-col px-6 pt-4 pb-4 gap-4 overflow-y-auto"
                            onWheel={handleWheel}
                        >
                            {(() => {
                                switch (page) {
                                    case 'overview':
                                        return <OverviewPage />;
                                    case 'google-apps-basic-access':
                                        return <GoogleAppsBasicAccessPage />;
                                    case 'google-apps-extended-access':
                                        return <GoogleAppsExtendedAccessPage />;
                                        case 'google-connected-devices':
                                        return <GoogleConnectedDevicesPage />;
                                    default:
                                        return <h1 data-testid="h1-9e4de5d6" >Unknown page {page}</h1>;
                                }
                            })()}
                        </div>
                    </div>
                </div>
            ) : (
                <MinimizedView onClick={() => setMinimized(false)} />
            )}
        </>
    );
};

const MinimizedView: React.FC<{ onClick: () => void }> = ({ onClick }) => {
    const recommendations = useRecommendationsStore((state) => state.allRecommendations);
    const [unHandledRecommendations, setUnHandledRecommendations] = useState<OAPRecommendation[]>([]);

    useEffect(() => {
        setUnHandledRecommendations(recommendations.filter(r => !r.resolved && !r.skipped));
    }, [recommendations]);

    return (
        <div data-testid="div-2ccd7510"  className="fixed top-20 right-0 z-[2147483627]">
            <div data-testid="div-b2b9d6eb"  className="oap-minimized-view flex items-center bg-backdrop rounded-l-lg p-4 cursor-pointer hover:scale-125 duration-300" onClick={onClick}>
                <div data-testid="div-f3a090a7"  className="relative">
                    <BGSvgIcon iconName="mb-logo-blue" width={24} height={24} />
                    {
                        unHandledRecommendations.length > 0 &&
                        <div data-testid="div-2f234b0e"  className="absolute bottom-[-5px] right-[-5px] w-4 h-4 rounded-md bg-red-600 dark:bg-[#F06666] text-backdrop border border-solid border-backdrop flex items-center justify-center">
                            <span data-testid="span-52d7c272"  className="text-xs font-bold leading-3 tracking-[0.1px]">{unHandledRecommendations.length}</span>
                        </div>
                    }
                </div>

            </div>
        </div>
    );
}


// @ts-ignore
window.createOAPResultsView = createOAPResultsView;
// @ts-ignore
window.closeOAPResultsView = closeOAPResultsView;
export { createOAPResultsView, closeOAPResultsView };
