import { BGSvgIcon } from "@/app/popup/src/components/core"
import { GoogleThirdPartyApp, GoogleThirdPartyAppPermission, OAPRecommendation } from "@/app/scripts/oap/types"
import { sendBackgroundMessage } from "@/utils/messaging/messaging";
import { DeleteConnectionRequest, DeleteConnectionResponse } from "@/utils/messaging/types";
import { MSG_OAP_DELETE_CONNECTION } from "@/app/scripts/app-consts";
import { useState } from "react";
import { t } from "$Popup/i18n";

const extensionRoot = chrome.runtime.getURL('app/popup/');
export const GoogleAppAccessCard: React.FC<{ app: GoogleThirdPartyApp, recommendation: OAPRecommendation, onConnectionDeleted: (app: GoogleThirdPartyApp, updatedRecommendation: OAPRecommendation) => void }> = ({ app, recommendation, onConnectionDeleted }) => {
    const [loading, setLoading] = useState(false);
    const [deleteFailed, setDeleteFailed] = useState<boolean>(false);

    const deleteConnectionClicked = async () => {
        setLoading(true);
        setDeleteFailed(false);
        try {
            const resp = await sendBackgroundMessage<DeleteConnectionRequest, DeleteConnectionResponse>({ type: MSG_OAP_DELETE_CONNECTION, payload: { app, recommendation } });
            if (resp.payload?.success === true) {
                // delete the app from the list
                onConnectionDeleted(app, resp.payload.updatedRecommendation);
            } else {
                setDeleteFailed(true);
            }
        } finally {
            setLoading(false);
        }
    }

    return (
        <div data-testid="div-fbc1fba8"  className="flex flex-col items-start gap-4 self-stretch py-4 px-6 rounded-2xl bg-backdrop border border-solid border-tragic-table-border">
            <div data-testid="div-61b8e7a4"  className="flex flex-col items-start justify-center gap-2 grow shrink-0 basis-0 w-full">
                {/* Name, access date and description */}
                <div data-testid="div-d0855a7d"  className="flex flex-col items-start gap-1">
                    {/* Title row */}
                    <div data-testid="div-3811d344"  className="flex flex-row items-center gap-2">
                        {/* TODO: app icon */}
                        <div data-testid="div-9b27df91"  className="flex flex-row items-center gap-1">
                            <span data-testid="span-bd0faf1d"  className="text-tragic">{app.name}</span>
                            <a data-testid="a-17a3c1ca"  className="cursor-pointer" target="_blank" href={fixLink(app.accessGivenTo || app.homePage)}>
                                <BGSvgIcon iconName="expand-right" width={16} height={16} iconRoot={extensionRoot} />
                            </a>
                        </div>
                    </div>
                    {app.accessGivenOn && <span data-testid="span-b531d1ab"  className="text-sm font-normal leading-5 tracking-[0.25px] text-tragic opacity-50">Access given on: {friendlyDate(app.accessGivenOn)}</span>}
                    <div data-testid="div-ab6f0504"  className="text-sm font-normal leading-5 tracking-[0.25px] text-tragic opacity-80">
                        {app.permissions.every((p) => p.weight === 0) ?
                            t('OAPBasicAccountAccess') :
                            <div data-testid="div-de890605"  dangerouslySetInnerHTML={{ __html: buildDescription(app.permissions) }} />
                        }
                    </div>
                </div>

                {/* See details and Delete connection buttons */}
                <div data-testid="div-ef847734"  className="flex flex-row justify-between self-stretch items-center">
                    <a data-testid="a-e52e05a2"  href={`https://myaccount.google.com/connections`}
                        className="flex flex-row justify-center items-start shrink-0 text-sm font-medium leading-5 tracking-[0.1px] text-primary cursor-pointer">
                        {t('OAPSeeDetails')}
                    </a>                    

                    <button data-testid="button-f4f30d51" 
                        onClick={deleteConnectionClicked}
                        disabled={loading}
                        className="flex flex-row min-w-[88px] px-4 py-2 justify-center items-center gap-1.5 rounded-[50px] bg-primary disabled:opacity-50 cursor-pointer">
                        {loading ? (
                            <span data-testid="span-ff7347a4"  className="text-center text-sm font-medium leading-5 tracking-[0.1px] text-backdrop">{t('OAPDeleting')}</span>
                        ) : (
                            <span data-testid="span-eab76185"  className="text-center text-sm font-medium leading-5 tracking-[0.1px] text-backdrop">{t('OAPDeleteConnection')}</span>
                        )}
                    </button>
                </div>

                {deleteFailed && <span data-testid="span-48185fe4"  className="text text-sm font-normal leading-5 text-danger">{t('OAPFailedToDeleteAppConnection')}</span>}
            </div>
        </div>
    )
}

function buildDescription(permissions: GoogleThirdPartyAppPermission[]): string {
    return permissions
        .map((p) => p.description)
        .join("<br>")
        .replace(/\n/g, "<br>");
}

function friendlyDate(isoDateString: string): string {
    const date = new Date(isoDateString);
    return date.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
}

function fixLink(link: string): string {
    if (link && link.startsWith("http")) {
        return link;
    }
    return `https://${link}`;
}